import{_ as o,o as c,c as d,a5 as t}from"./chunks/framework.BfQ7H7Qx.js";const p=JSON.parse('{"title":"Service Boundaries & Domain Ownership — BrandHub Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/service-boundaries.md","filePath":"architecture/service-boundaries.md"}'),a={name:"architecture/service-boundaries.md"};function r(i,e,s,n,l,u){return c(),d("div",null,[...e[0]||(e[0]=[t('<h1 id="service-boundaries-domain-ownership-—-brandhub-architecture" tabindex="-1">Service Boundaries &amp; Domain Ownership — BrandHub Architecture <a class="header-anchor" href="#service-boundaries-domain-ownership-—-brandhub-architecture" aria-label="Permalink to &quot;Service Boundaries &amp; Domain Ownership — BrandHub Architecture&quot;">​</a></h1><p>&gt; Navigation: <a href="./../">← Knowledge Base Hub</a> · <a href="./README.html">← Architecture Index</a> · <a href="./technical-overview.html">Technical Overview</a> · <a href="/brandhub-infrastructure/view.html?file=architecture/db-ownership-diagram.html">DB Ownership Diagram</a></p><p>Defines the non-negotiable runtime, data-ownership, and communication boundaries across every service in the BrandHub ecosystem (<code>Agency / Personal Studio → Workspace → Media Package → Media Campaign → Task → Post</code>).</p><hr><h2 id="_1-brandhub-api-gateway-java-21-spring-cloud-gateway-webflux-8080" tabindex="-1">1. <code>brandhub-api-gateway</code> (Java 21, Spring Cloud Gateway WebFlux, <code>:8080</code>) <a class="header-anchor" href="#_1-brandhub-api-gateway-java-21-spring-cloud-gateway-webflux-8080" aria-label="Permalink to &quot;1. `brandhub-api-gateway` (Java 21, Spring Cloud Gateway WebFlux, `:8080`)&quot;">​</a></h2><ul><li><strong>Owns</strong>: <ul><li><strong>Redis Namespace (Write/Read)</strong>: <code>ratelimit:gateway:{userId|ip}:{minute}</code> (<code>60s</code> TTL via reactive Lua <code>INCR</code> + <code>EXPIRE</code> in <code>RateLimitGatewayFilterFactory</code>).</li><li><strong>Redis Namespace (Read-Only)</strong>: <code>jwt:blacklist:{jti}</code> (<code>JwtUtil.validateAndExtract()</code>).</li><li><strong>Perimeter Filter Pipeline</strong>: <code>RequestIdWebFilter</code> (<code>X-Request-Id</code>), <code>InboundSecurityWebFilter</code> (blocks <code>;</code>/<code>..</code>/<code>%2e%2e</code> path smuggling, blocks <code>/api/v1/internal/**</code> and <code>/api/v1/test/**</code>, strips spoofed <code>X-User-Id</code>, <code>X-User-Role</code>, <code>X-Workspace-Id</code>, <code>X-Internal-Key</code> headers), <code>JwtAuthFilterGatewayFilterFactory</code> (<code>JWT_PUBLIC_KEY</code> RS256 verification), <code>LoggingGlobalFilter</code>, and <code>GlobalErrorWebExceptionHandler</code> (<code>ApiResponse&lt;T&gt;</code> JSON errors).</li></ul></li><li><strong>Does NOT Own</strong>: Zero PostgreSQL, MongoDB, ChromaDB, Neo4j, or RabbitMQ connections; holds <strong>no</strong> <code>JWT_PRIVATE_KEY</code> or <code>AES_SECRET_KEY</code>; performs <strong>no</strong> workspace-membership RBAC queries.</li></ul><hr><h2 id="_2-brandhub-business-service-java-21-spring-boot-3-8081" tabindex="-1">2. <code>brandhub-business-service</code> (Java 21, Spring Boot 3, <code>:8081</code>) <a class="header-anchor" href="#_2-brandhub-business-service-java-21-spring-boot-3-8081" aria-label="Permalink to &quot;2. `brandhub-business-service` (Java 21, Spring Boot 3, `:8081`)&quot;">​</a></h2><ul><li><strong>Owns</strong>: <ul><li><strong>PostgreSQL 17 — All <code>97</code> Tables (<code>100%</code> Exclusive Owner)</strong>: <ul><li><em>Identity &amp; System Roles</em>: <code>users</code>, <code>user_oauth_providers</code>, <code>user_refresh_tokens</code>, <code>user_system_roles</code>, <code>account_activation_tokens</code>.</li><li><em>Organization (<code>AGENCY</code> &amp; <code>PERSONAL</code>)</em>: <code>agencies</code> (<code>owner_id</code>, <code>company_type</code>), <code>agency_members</code>, <code>agency_invitations</code>, <code>client_profiles</code>, <code>workspaces</code>, <code>workspace_members</code> (<code>MANAGER</code> | <code>CREATOR</code> | <code>CLIENT</code>), <code>workspace_invitations</code>, <code>workspace_templates</code>, <code>workspace_post_templates</code>, <code>workspace_hashtags</code>.</li><li><em>Media Packages, Campaigns &amp; Collaborators</em>: <code>media_packages</code>, <code>workspace_media_packages</code>, <code>package_negotiation_events</code>, <code>media_campaigns</code>, <code>campaign_versions</code>, <code>campaign_review_events</code>, <code>campaign_deployments</code>, <code>content_request_completion_jobs</code>, <code>third_party_collaborators</code>, <code>campaign_collaborators</code>.</li><li><em>SePay (VietQR) Billing &amp; Double-Entry AI Credits</em>: <code>subscription_plans</code> (<code>STUDIO_FREE/PLUS/PRO</code>, <code>BASIC/PLUS/ENTERPRISE</code>), <code>billing_plan_versions</code>, <code>billing_plan_cycle_prices</code>, <code>billing_plan_change_log</code>, <code>agency_subscriptions</code>, <code>billing_orders</code>, <code>billing_payments</code>, <code>billing_payment_events</code>, <code>transactions</code>, <code>agency_credit_wallets</code>, <code>credit_grants</code>, <code>workspace_credit_limits</code>, <code>ai_credit_operation_prices</code>, <code>ai_credit_reservations</code>, <code>credit_operations</code>, <code>credit_entries</code>.</li><li><em>Product Video Coordinator, Storage/Drive/Vault, Mail &amp; Governance</em>: <code>ai_caption_generations</code>, <code>ai_video_jobs</code>, <code>product_video_*</code> (<code>5</code> tables), <code>agency_storage_*</code>, <code>storage_addon_*</code>, <code>client_vault_*</code>, <code>repository_drive_*</code>, <code>mail_*</code>, <code>newsletter_usage</code>, <code>engagement_reminders</code>, <code>audit_logs</code>, <code>user_strikes</code>, <code>sanction_reviews</code>, <code>content_moderation_reviews</code>, <code>admin_*</code>, <code>user_notifications</code> (<code>LISTEN/NOTIFY</code>).</li></ul></li><li><strong>MongoDB 7.0 — <code>49</code> of <code>52</code> Collections</strong>: <code>tasks</code>, <code>task_approvals</code>, <code>task_comments</code>, <code>task_comment_uploads</code>, <code>task_notification_outbox</code>, <code>task_sections</code>, <code>task_section_versions</code>, <code>task_section_events</code>, <code>event_plans</code>, <code>press_recommendations</code>, <code>content_requests</code>, <code>posts</code>, <code>post_versions</code>, <code>social_accounts</code>, <code>materials</code>, <code>material_folders</code>, <code>material_versions</code>, <code>material_upload_sessions</code>, <code>material_references</code>, <code>material_audit_outbox</code>, <code>client_vault_shares</code>, <code>watermark_presets</code>, <code>chat_*</code> (<code>8</code> collections), <code>video_*</code> (<code>4</code> collections), <code>surveys</code>, <code>survey_responses</code>, <code>mail_templates</code>, <code>mail_recipient_groups</code>, <code>monitoring_*</code> (<code>4</code> collections), <code>notifications</code>, <code>report_jobs</code>, plus V1 seed-compat collections.</li><li><strong>Redis Namespaces</strong>: <code>jwt:blacklist:{jti}</code>, <code>oauth:state:{state}</code>, OTP/2FA challenge keys.</li><li><strong>S3 Cryptographic Envelope (<code>RepositoryEnvelopeCrypto</code>)</strong>: Pre-encrypts and streams <code>repository/*</code> and <code>client-vault/*</code> objects using <code>ALG_AES_256_GCM_HKDF_SHA512_COMMIT_KEY</code>.</li><li><strong>STOMP WebSockets</strong>: <code>/ws/tasks</code> (Yjs CRDT collaborative content &amp; awareness) and <code>/ws/chat</code> (workspace chat, Agora call signaling, and <code>/user/queue/notifications</code>).</li></ul></li><li><strong>Does NOT Own</strong>: Never invokes external Facebook/Instagram/TikTok/Threads publishing APIs directly; never embeds vectors into ChromaDB or traverses Neo4j directly.</li></ul><hr><h2 id="_3-brandhub-ai-service-python-3-11-fastapi-8082" tabindex="-1">3. <code>brandhub-ai-service</code> (Python 3.11+, FastAPI, <code>:8082</code>) <a class="header-anchor" href="#_3-brandhub-ai-service-python-3-11-fastapi-8082" aria-label="Permalink to &quot;3. `brandhub-ai-service` (Python 3.11+, FastAPI, `:8082`)&quot;">​</a></h2><ul><li><strong>Owns</strong>: <ul><li><strong>ChromaDB <code>1.5.9</code></strong>: Per-client/workspace <code>384d</code> vector collections (<code>client_{clientId}</code> / <code>brandhub_rag</code> with mandatory <code>where={&quot;clientId&quot;: ...}</code> filter).</li><li><strong>Neo4j <code>5.26</code> / Aura</strong>: Trend Knowledge Graph (<code>:Trend</code>, <code>:CrawledPost</code>, <code>:KOL</code>, <code>:Brand</code>, <code>:Location</code>, <code>:Dish</code>) + APOC Entity Resolution (<code>Neo4jTrendService</code>).</li><li><strong>MongoDB — <code>2</code> Collections</strong>: <code>knowledge_documents</code> and <code>ai_usage_logs</code>.</li><li><strong>Redis Namespace</strong>: <code>trends:vn:{YYYY-MM-DD}:{category}</code> (<code>6h</code> TTL) and trend snapshot/brand-fit caches.</li><li><strong>S3 Prefixes</strong>: <code>rag/*</code>, <code>ai/*</code>, and <code>qwen-ambassador/*</code> on <code>brandhub-media-134875421878</code>, plus raw trend archives on <code>crawler-social-134875421878</code>.</li></ul></li><li><strong>Does NOT Own</strong>: Zero connection to PostgreSQL or business MongoDB collections; never mutates <code>agency_credit_wallets</code> or <code>ai_credit_reservations</code> (all credit accounting stays in <code>business-service</code>).</li><li><strong>Key Subsystems</strong>: <ul><li>Multi-provider LLM routing (<code>Groq</code>, <code>Google Gemini</code>, <code>Claude</code>) + <code>Humanizer</code> + <code>PhoBERT</code> emotion/sentiment + <code>text_moderation_service</code> (<code>FR 3.6.33</code>).</li><li>Remote <strong>Vast.ai GPU Worker</strong> orchestration: <code>qwen_ambassador_client.py</code> (Virtual Brand Ambassador &amp; 3-reference commercial photography) and <code>ltx_director.py</code> (Claude storyboard/segment director → <strong>Wan 2.2 Fun VACE 14B</strong> <code>:10200</code> worker + <code>ffmpeg</code> CC0 music post-mix).</li><li><code>server_video_edit</code> orchestration against <code>brandhub-edit-video</code> (<code>172.31.20.80:8095</code>) and trend ingestion via <code>CrawlBatchConsumer</code> + <code>brandhub-crawl</code> (<code>172.31.20.50:8084</code> via <code>crawl-gate</code>).</li></ul></li></ul><hr><h2 id="_4-brandhub-publisher-service-java-21-spring-boot-3-8083" tabindex="-1">4. <code>brandhub-publisher-service</code> (Java 21, Spring Boot 3, <code>:8083</code>) <a class="header-anchor" href="#_4-brandhub-publisher-service-java-21-spring-boot-3-8083" aria-label="Permalink to &quot;4. `brandhub-publisher-service` (Java 21, Spring Boot 3, `:8083`)&quot;">​</a></h2><ul><li><strong>Owns</strong>: <ul><li><strong>MongoDB — <code>1</code> Collection</strong>: <code>publish_logs</code> (platform HTTP request/response audit telemetry).</li><li><strong>RabbitMQ Publishing Queues</strong>: <code>publisher.job.exchange</code> → <code>publisher.job.queue</code>, <code>publisher.retry.exchange</code> → <code>publish.jobs.retry.{1m,5m,15m}</code>, and <code>publisher.job.dlx</code> → <code>publisher.job.dlq</code>.</li><li><strong>Redis Lock Namespace</strong>: <code>processingPostIds:{postId}:{platform}</code> (<code>30m</code> TTL in <code>PublishJobConsumer</code>).</li></ul></li><li><strong>Does NOT Own</strong>: Zero PostgreSQL access and zero direct access to <code>posts</code> or <code>social_accounts</code> in MongoDB (syncs encrypted OAuth credentials and publish results with <code>business-service</code> via internal <code>X-Internal-Key</code> endpoints <code>/api/v1/internal/social-accounts/*</code> and publish result callbacks).</li><li><strong>Supported Social Adapters (<code>SocialPlatform</code> Enum — Strictly 4 Platforms)</strong>: <ol><li><code>FacebookPublishAdapter</code> (<code>FR 3.8.8</code> Post, <code>FR 3.8.9</code> Story, <code>FR 3.8.10</code> Reels — Meta Graph <code>v19.0</code>)</li><li><code>InstagramPublishAdapter</code> (<code>FR 3.8.11</code> Post, <code>FR 3.8.12</code> Reels, <code>FR 3.8.13</code> Story — Meta Graph <code>v19.0</code>)</li><li><code>TikTokPublishAdapter</code> (<code>FR 3.8.14</code> Video — TikTok Content Posting API v2)</li><li><code>ThreadsPublishAdapter</code> (<code>FR 3.8.15</code> Post — Threads Publishing API) <em>(External offline/partner channels such as KOL/KOC, Online Newspaper, Banner Ads, and TV Channels — <code>FR 3.7.15</code>–<code>3.7.18</code> — are tracked as collaborator deliverables in <code>business-service</code>, never through <code>publisher-service</code>.)</em></li></ol></li></ul><hr><h2 id="_5-auxiliary-compute-client-boundaries" tabindex="-1">5. Auxiliary Compute &amp; Client Boundaries <a class="header-anchor" href="#_5-auxiliary-compute-client-boundaries" aria-label="Permalink to &quot;5. Auxiliary Compute &amp; Client Boundaries&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Component</th><th style="text-align:left;">Runtime</th><th style="text-align:left;">Boundary Contract</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>brandhub-crawl</code></strong></td><td style="text-align:left;">Python + Playwright/Camoufox (<code>172.31.20.50:8084</code>, wakeable)</td><td style="text-align:left;">Executes headless social scraping; streams raw batches over RabbitMQ to <code>ai-service</code> (<code>CrawlBatchConsumer</code>); woken via <code>crawl-gate</code> (<code>172.31.24.149:8084</code>) or EventBridge SSM <code>crawl-kick.sh</code></td></tr><tr><td style="text-align:left;"><strong><code>brandhub-edit-video</code></strong></td><td style="text-align:left;">Containerized Render Engine (<code>172.31.20.80:8095</code>, wakeable)</td><td style="text-align:left;">Reached via Gateway Nginx <code>/edit-video/</code> (<code>X-API-Key</code>) or <code>ai-service</code> <code>server_video_edit</code>; pulls/uploads media via short-lived <code>/api/v1/internal/video-edits/{jobId}/*</code> sessions</td></tr><tr><td style="text-align:left;"><strong><code>brandhub-web</code> &amp; <code>brandhub-mobile-app</code></strong></td><td style="text-align:left;">React 19 / Vite 8 &amp; Expo 58 / RN 0.88</td><td style="text-align:left;">Communicate <strong>exclusively</strong> through <code>api.brandhub.id.vn</code> (<code>:8080</code> locally) over HTTPS REST and <code>/ws/{chat,tasks}</code> STOMP; never hold AWS S3 IAM keys or AI provider secrets</td></tr></tbody></table>',18)])])}const b=o(a,[["render",r]]);export{p as __pageData,b as default};
